create extension if not exists "uuid-ossp";
create type public.app_role as enum ('admin','project_manager','engineer','customer');
create table public.profiles(id uuid primary key references auth.users on delete cascade,full_name text not null,role app_role not null default 'engineer',created_at timestamptz default now());
create table public.projects(id uuid primary key default uuid_generate_v4(),name text not null,customer text not null,status text not null default '需求分析',progress int not null default 0 check(progress between 0 and 100),risk text not null default '低',pm_id uuid references profiles,engineer_id uuid references profiles,start_date date,delivery_date date,description text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.project_members(project_id uuid references projects on delete cascade,user_id uuid references profiles on delete cascade,member_role app_role not null,primary key(project_id,user_id));
create table public.requirements(id uuid primary key default uuid_generate_v4(),project_id uuid references projects on delete cascade,title text not null,detail text,category text,priority text default '中',status text default '待确认',owner_id uuid references profiles,customer_confirmed boolean default false,created_at timestamptz default now());
create table public.test_cases(id uuid primary key default uuid_generate_v4(),project_id uuid references projects on delete cascade,title text not null,objective text,preconditions text,steps jsonb default '[]',expected_result text,actual_result text,result text default 'NOT_RUN',owner_id uuid references profiles,created_at timestamptz default now());
create table public.tasks(id uuid primary key default uuid_generate_v4(),project_id uuid references projects on delete cascade,title text not null,status text default '待处理',owner_id uuid references profiles,planned_start date,planned_end date,actual_start date,actual_end date,notes text,created_at timestamptz default now());
create table public.risks(id uuid primary key default uuid_generate_v4(),project_id uuid references projects on delete cascade,title text not null,severity text not null,probability text not null,status text default 'Open',owner_id uuid references profiles,mitigation text,due_date date,created_at timestamptz default now());
create table public.milestones(id uuid primary key default uuid_generate_v4(),project_id uuid references projects on delete cascade,title text not null,status text default '待开始',planned_date date,actual_date date,sort_order int default 0);
create table public.handover_items(id uuid primary key default uuid_generate_v4(),project_id uuid references projects on delete cascade,category text not null,title text not null,completed boolean default false,completed_by uuid references profiles,completed_at timestamptz);
create table public.attachments(id uuid primary key default uuid_generate_v4(),project_id uuid references projects on delete cascade,bucket_path text not null,file_name text not null,uploaded_by uuid references profiles,created_at timestamptz default now());
create table public.comments(id uuid primary key default uuid_generate_v4(),project_id uuid references projects on delete cascade,entity_type text not null,entity_id uuid not null,content text not null,author_id uuid references profiles,created_at timestamptz default now());
alter table profiles enable row level security; alter table projects enable row level security; alter table project_members enable row level security; alter table requirements enable row level security; alter table test_cases enable row level security; alter table tasks enable row level security; alter table risks enable row level security; alter table milestones enable row level security; alter table handover_items enable row level security; alter table attachments enable row level security; alter table comments enable row level security;
create or replace function public.my_role() returns app_role language sql stable security definer set search_path=public as $$select role from profiles where id=auth.uid()$$;
create policy "profiles self or admin" on profiles for select using(id=auth.uid() or my_role()='admin');
create policy "project members read" on projects for select using(my_role()='admin' or exists(select 1 from project_members m where m.project_id=id and m.user_id=auth.uid()));
create policy "pm manage projects" on projects for all using(my_role() in ('admin','project_manager')) with check(my_role() in ('admin','project_manager'));
create policy "members visible" on project_members for select using(user_id=auth.uid() or my_role() in ('admin','project_manager'));
create policy "pm manages members" on project_members for all using(my_role() in ('admin','project_manager')) with check(my_role() in ('admin','project_manager'));
do $$ declare t text; begin foreach t in array array['requirements','test_cases','tasks','risks','milestones','handover_items','attachments','comments'] loop execute format('create policy "project member read %1$s" on %1$I for select using (my_role() = ''admin'' or exists(select 1 from project_members m where m.project_id=%1$I.project_id and m.user_id=auth.uid()))',t); execute format('create policy "team write %1$s" on %1$I for all using (my_role() in (''admin'',''project_manager'',''engineer'')) with check (my_role() in (''admin'',''project_manager'',''engineer''))',t); end loop; end $$;
alter publication supabase_realtime add table projects, requirements, test_cases, tasks, risks, milestones, handover_items, comments;
